/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, a=0;
  wire match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));
  always #5 clk=~clk;

  task send(input bit b);
    begin
      a=b;
      @(posedge clk);
      #1;
      "'$display("t=%0t a=%0b a_tem=%09b match=%0b", $time, a, dut.a_tem, match);
    end
  endtask

  initial begin
    repeat(1) @(posedge clk);
    rst_n=1;
    // pattern 011000110 should match when 9th bit received
    send(0); send(1); send(1); send(0); send(0); send(0); send(1); send(1); send(0);
    // extra cycle
    send(0);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

